_bizOvMonthParts:
function _bizOvMonthParts(mon){
  var t=String(mon||'').trim(), out=[], seen={};
  if(!t)return out;
  if(/연중|상시|전체/.test(t)){ for(var i=1;i<=12;i++)out.push(i); return out; }
  var m, re=/(1[0-2]|[1-9])\s*월?/g;
  while((m=re.exec(t))){ var n=+m[1]; if(!seen[n]){seen[n]=1;out.push(n);} }
  return out;
}

