    var isRent=(ct==='대관');
    var s=n8(p['시작일']),e=n8(p['종료일'])||s;
    var sch=(function(){ var a=d8(s),b=d8(e); return (b&&b!==a)?(a+'~'+b):a; })();
    var yr=s?Math.floor(s/10000):null;
    var name=String(p['풀네임']||'').trim();
    var short=String(p['줄임말']||'').trim();
