      var rec={id:id,연도:yr,구분:gu,명칭:name,일정:sch,장소:fields.장소,횟수:fields.횟수,수강인원:null,출처:'programs',비고:null,앱_프로그램명:null,
        사업비:null,수입:null,수익률:null,무료여부:null,사업비분할:null,수입분할:null,구분2:(isRent?'대관':'기획'),사업코드:fields.사업코드,분야:bun,
        _s:fields._s,_e:fields._e,_ps:fields._ps,_hs:fields._hs,_st:'',_wg:0,_g2:fields._g2,별칭:(short?[short]:null),보고서명:null};
