//   무슨 일이 있었나: `#srail-uha`는 **자기 유리 패널**을 CSS로 들고 있고(L2406 배경·blur·테두리·그림자),
//   그걸 지우는 규칙은 `#app.biz-mode #sales-rail #rail-yrm #srail-uha` = **슬롯 안에 있을 때만** 걸린다.
//   그런데 좁은 화면 판매 실적 면이 그 노드를 `#sales-rail` 바로 밑으로 옮겨 놓고(`_bizInlineRender` page===2),
//   사업 개요로 돌아와도 아무도 안 돌려놨다 → 슬롯 밖이라 규칙이 풀려 **빈 유리 창이 5시 방향에 되살아났다**.
//   지우지 않고 **제자리+숨김**으로 두는 이유 = 판매 현황 덱이 그 노드를 그대로 다시 쓴다(지우면 상세가 갈 곳을 잃는다).

_finFromSeed:
function _finFromSeed(s,year){
  return {no:s.no,y:year,cat:s.cat,acct:s.acct,name:s.name,lnk:String(s.lnk||''),mon:s.mon,cnt:s.cnt,bud:s.bud,vou:s.vou,
    fee:s.fee,rev:s.rev,paid:s.paid,inv:s.inv,memo:'',by:'',at:'',blank:String(s.blank||''),tag:String(s.tag||''),src:'seed'};
}
// 한 해의 사업비 = 시트 행 ∪ (시트에 없는 NO의 씨앗). 시트가 이긴다.

_bizExhibRows:
function _bizExhibRows(year){
  if(!(typeof _anaState!=='undefined'&&_anaState&&_anaState._exMaster))return null;
  var out=[];
  try{
    _anaExhibBuild().forEach(function(e){
      if(e.free)return;
      var sd=_salesDate(e.시작일), ed=_salesDate(e.종료일);
      var y=e.year||(sd?sd.getFullYear():null);
      if(y!==year)return;
      var paid=_salesNum(e.최종유료)||0, tot=_salesNum(e.최종총인원)||0, goal=_salesNum(e.목표관객)||0, rev=_salesNum(e.최종매출)||0;
      var head=tot||paid;
      out.push({name:e.name,genre:'전시',_col:_bizExCol(e.name,''),   // [260805 운영자] 색 = **캘린더 전시선과 같은 것**(_EX_SPACE·_exLaneOf 정본 공유) · ⚠ Plotly는 CSS var()를 못 읽어 런타임 해석값으로 넘긴다 = 소스 raw hex 0
        start:sd||ed||null,end:ed||sd||null,cnt:_salesNum(e.운영일수)||0,
        paid:head,seat:goal,
        avg:(goal>0)?(head/goal*100):(parseFloat(e.occ)||0),
        _rev:(rev>0?rev:null),_sold:(head>0?head:null),
        _dly:e.daily||[],   // [260804 운영자] 누적범위 그래프용 일일 누계 실측점(전시일일 · _anaExhibBuild가 이미 정렬해 둔 참조 전달 — 재집계 0)
        _st:(e.status==='active')?'active':((e.status==='notyet')?'planned':'ended')});
    });
  }catch(_e){ console.warn('[biz exhib rows]',_e); return []; }
  // [260805 운영자 「깃에 전시 실적 넣어놨다 — 상반기 것도 채워줘」] 전시 실적 거울 합류(data/exhib_daily_2026.js ·
  //   기계산출물 = tools/build_exhib_daily.py가 일일보고 xlsx에서 생성). **전시DB(전시마스터·전시일일)가 정본** —
  //   거울은 DB에 없는 전시만 보충한다. 같은 전시 판정 = 정규화 이름 동일 or DB 이름이 거울 이름을 포함
  //   (「GS칼텍스 … <숨: 쉬는 섬>」 ⊃ 거울 「숨 쉬는 SUM」 실측) — 값 이원화 0. 무료 행사(free)는 기존 제외 규칙 그대로.
  try{
    if(typeof EXHIB_DAILY_2026!=='undefined'&&EXHIB_DAILY_2026&&EXHIB_DAILY_2026.year===year){
      var _mHave=out.map(function(g){return _uName(g.name||'');});
      var _mTdy=new Date(); _mTdy.setHours(0,0,0,0);
      (EXHIB_DAILY_2026.list||[]).forEach(function(m){
        if(m.free)return;                                        // 무료 = 판매 축 밖(_anaExhibBuild 규칙 계승)
        var k=_uName(m.name||''); if(!k)return;
        if(_mHave.some(function(h){ return h===k||(k.length>=6&&h.indexOf(k)>=0); }))return;
        var sd=_salesDate(m.start), ed=_salesDate(m.end);
        out.push({name:m.name,genre:'전시',_col:_bizExCol(m.name,''),
          start:sd||ed||null,end:ed||sd||null,cnt:m.days||0,
          paid:(m.tot||m.paid||0),seat:0,avg:0,                  // 목표관객 축 없음(거울엔 목표 「매출」뿐) → 달성률 생략
          _rev:((m.rev>0)?m.rev:null),_sold:((m.tot>0)?m.tot:null),
          // [260807-20 운영자 「정산서에 인원과 함께 누적 판매 금액도 담겨져 있다 — 매출 토글 켜질 때 전시도 바뀌게」]
          //   ⚠ 구판은 거울 daily의 **4번째 칸(누계 금액)을 통째로 버렸다** — 파일 머리 주석이 이미
          //   `[기준일자, 누계 총인원, 누계 유료, 누계 총 금액(원)]`이라 적고 있는데 옮겨 담는 자리에서 셋만 집었다.
          //   그래서 정산서 금액이 레포에 **이미 들어와 있는데도** 화면에 매출 축을 세울 수가 없었다(값 창작 0 계약상 빈 축).
          //   전시DB 경로(`_anaExhibBuild` → 전시일일)는 원본 행을 그대로 넘겨 이미 `누계금액`을 들고 있다 = 두 경로가 같은 열 이름으로 만난다.
          _dly:(m.daily||[]).map(function(p){return {'기준일자':p[0],'누계총인원':p[1],'누계유료':p[2],'누계금액':p[3]};}),
          _st:(ed&&ed<_mTdy)?'ended':((sd&&sd>_mTdy)?'planned':'active')});
      });
    }
  }catch(_e){ console.warn('[biz exhib mirror]',_e); }
  out.sort(function(a,b){ var ad=a.end?a.end.getTime():9e15,bd=b.end?b.end.getTime():9e15; if(ad!==bd)return ad-bd; return a.name<b.name?-1:1; });
  return out;
}
// [260804 운영자 「교육도 세우고 · 무조건 당해년도만 · 해당 월에 콘텐츠를 세우셈」] 교육 반쪽 = **당해 연도 월별 일정 게이지**.
//   구 260806 「연도별 수강생 가로 막대」(여러 해 겹침)는 철거 — 소스를 연간 거울(_YR)에서 **프로그램 시트(콘텐츠구분 예술교육 = t'a')**로
//   바꿔, 선택 연도의 교육 프로그램을 공연과 같은 1월~12월 축 위 그 달 자리에 세운다.
//   ⚠ 프로그램 **단위** 수강생 원천은 여전히 없다(있는 건 연간 거울 총계뿐 · 라우터 경고 축) → 막대 값을 창작하지 않고
//     전부 「값 없음」 파선 게이지(공연 예정과 같은 문법)로 세운다 · 수강생 수치는 툴팁도 말하지 않는다(집계 전 명시).

_bizEduMonthRows:
function _bizEduMonthRows(year){
  // [260808 운영자 「전시랑 교육이 처음 로딩될 때 오류처럼 나온다 · 바로 못 받아오면 로딩처럼」]
  //   ⚠ **프로그램 시트 미도착 = 「없어요」 확정 금지**(로딩 유지) — 이 반쪽의 유일한 소스가 PERFS인데
  //   구판은 「아직 안 왔다」와 「진짜 0건」을 구분하지 않아, 부팅 중 PERFS가 운영대장보다 늦게 오는 창에서
  //   「📭 2026년 교육 프로그램이 없어요」가 2초가량 떴다(실측 재현: 프로그램 3.2s / 운영·전시 0.9s → 1.68~3.66s 노출).
  //   같은 규약이 이미 판매 레일에 있다(_perfReady 게이트 ~L8105 「master 도착 전에는 '없어요' 확정 금지」)
  //   · 반환 계약도 전시 반쪽과 같은 축으로 맞춘다(_bizExhibRows: 미로드 = null → 호출측이 로딩 화면).
  //   ⚠ _perfReady는 loadPrograms가 **실패해도** true가 된다(.catch 후 .then) = 무한 로딩 아님.
  if(typeof _perfReady!=='undefined'&&!_perfReady)return null;
  var out=[], col=_yrCss('--green')||'';
  var tdy=new Date(); tdy.setHours(0,0,0,0);
  // [260805 운영자 「화요살롱 … 160개 팔렸다고 · db에도 동일하게」] 수강생 **실값 조인** — 공연 목록이 쓰는 그 축을 그대로 쓴다.
  //   ① 운영대장(세부운영관리대장) 교육 행 = 끝난 교육의 정본(발권유료 = 그 프로그램 수강 인원)
  //   ② 판매 축(_salesBuild → _bizSalesIdx) = 지금 팔고 있는 교육(일일입력 누계)
  //   ⚠ 여기서 새로 집계하지 않는다 — ①은 원본 행 합, ②는 정본 산출물 조회. 값이 **둘 다 없으면 종전대로 파선**(창작 0).
  var opsIdx=_bizEduOpsIdx(year), sx=null, dlyIdx=_bizEduDailyIdx(year);
  try{ sx=_bizSalesIdx(year); }catch(_e){}
  var attach=function(g){
    var k=_uName(g.name||'');
    var o=opsIdx?opsIdx[k]:null, p=(sx&&sx[k])?sx[k]:null, fbr=null;
    var v=(o&&o.paid>0)?o.paid:((p&&isFinite(p.seats)&&p.seats>0)?p.seats:null);
    if(v==null){ fbr=_bizEduFallbackRow(g.name,g.end); if(fbr&&fbr.v>0){ v=fbr.v; g._vsrc='운영자 확정'; } }   // 실값 둘 다 없을 때만 = 폴백(위 규칙표 주석 · 부분 일치 + 종료 연·월)
    if(v!=null){ g.paid=v; g._sold=v; }
    if(o&&o.genre)g._g2=o.genre;
    if(p&&isFinite(p.money)&&p.money>0)g._rev=p.money;
    // [260807-20 운영자 「교육은 지금 있는거 매출이 160 × 3만5천원 · 이거로 수치 db에 넣어서 교육도 바뀌게」]
    //   폴백 매출 = **수량 × 단가**(둘 다 위 표의 확정값) — 곱은 여기서 한 번만 한다(5,600,000을 어디에도 안 적는다).
    //   ⚠ 계약은 종전 그대로 **실값이 이긴다** — 판매 축 금액(`p.money`)이 이미 들어왔으면 위 줄이 잡고 이 줄은 안 탄다.
    if(g._rev==null&&fbr&&fbr.v>0&&fbr.p>0)g._rev=fbr.v*fbr.p;
    // [260805 운영자 「종료 안된거는(판매중일경우는, 공연과 같이) … 동시에 팔릴경우는 누적그래프로」]
    //   **아직 안 끝난** 교육에만 월별 누계를 단다 — 끝난 교육의 정본은 운영대장 발권유료 한 값이라 시계열이 없고,
    //   운영자 판정도 「이미 종료된 건 지금(막대) 그대로」다. 값 창작 0(원천이 없으면 종전대로 파선).
    if(g._st!=='ended'){ var d0=dlyIdx?dlyIdx[k]:null;
      if(d0&&d0.mo&&d0.mo.length)g._mo=d0.mo;
      if(d0&&d0.rev&&d0.rev.length)g._moRev=d0.rev; }
    // [260807-20 운영자 「교육 실제로 팔리는건 **꾸준히 팔려왔다** — 판매 기간을 5월부터 6월까지 두개로 나누고
    //   **65 > 160(+95)** 이렇게 꺾은선으로 동일하게 표현해주라 · **기획전시처럼**」]
    //   → 구 260805의 「끝난 교육은 막대 그대로」는 **이 지시로 개정**된다. 그때 막대였던 근거는 「끝난 교육의 정본이
    //   운영대장 한 값이라 **시계열이 없다**」였는데, 운영자가 그 시계열(5월 65 → 6월 160)을 확정해 줬으므로 근거가 사라졌다.
    //   ⚠ 여전히 값 창작 0 — 그리는 건 위 표에 적힌 그 두 점뿐이고, 없는 프로그램은 종전대로 막대·파선이다.
    //   ⚠ 실값이 이긴다: 일일입력 시계열(`_mo`)이 들어와 있으면 그쪽을 그대로 두고 이 줄은 안 탄다.
    if(!(g._mo&&g._mo.length)&&fbr){
      var fmo=_bizEduMoParse(fbr);
      if(fmo){ g._mo=fmo;
        if(fbr.p>0)g._moRev=fmo.map(function(q){ return [q[0],q[1]*fbr.p]; });   // 월별 매출 = 그 달 누계 수량 × 같은 단가
        g._vsrc='운영자 확정'; }
    }
    return g;
  };
  var seen={};
  ((typeof PERFS!=='undefined'&&PERFS)||[]).forEach(function(p){
    if(!p||p.t!=='a'||!p.s)return;
    var sd=_salesDate(p.s); if(!sd||sd.getFullYear()!==year)return;
    var ed=p.e?(_salesDate(p.e)||sd):sd;
    var nm=String(p.f||p.n||'').trim(); if(!nm)return;
    seen[_uName(nm)]=1;
    out.push(attach({name:nm,genre:'교육',_col:col,start:sd,end:ed,cnt:0,paid:0,seat:0,avg:0,
      _g2:String(p.g2||p.g||'').trim()||'',   // 프로그램 시트 장르(예: 인문학) — 툴팁이 말한다
      _rev:null,_sold:null,   // 조인 실패 = 파선 게이지(_bizDrawSalesBars dom='edu') — 수강생 창작 금지
      _st:(ed<tdy)?'ended':((sd>tdy)?'planned':'active')}));
  });
  // 프로그램 시트엔 없고 운영대장에만 있는 교육(과거 소급 등)도 싣는다 — 공연 목록의 ∪ 규칙과 같은 축.
  if(opsIdx)Object.keys(opsIdx).forEach(function(k){
    if(seen[k])return;
    var o=opsIdx[k]; if(!o||!o.start)return;
    out.push({name:o.name,genre:'교육',_col:col,start:o.start,end:o.end||o.start,cnt:o.cnt||0,
      paid:o.paid||0,seat:0,avg:0,_g2:o.genre||'',_rev:null,_sold:(o.paid>0?o.paid:null),
      _st:((o.end||o.start)<tdy)?'ended':'active'});
  });
  out.sort(function(a,b){ return (a.start-b.start)||(a.name<b.name?-1:1); });
  // [260806-11] 구 교육 색인(①②③… · 260805 「인덱싱 열 부여」) **부여까지 철거** — 표기를 지우면서 쓰는 곳이
  //   0이 됐다(게이지 라벨·툴팁 머리 셋이 전부였다). 되살릴 땐 시작일순 원문자라는 그 규칙 그대로.
  return out;
}
// ── [260804 운영자] y축 중략(≈) — 「매출이 너무 큰 게 하나 있어서 차트가 무너진다」 ────────────────
//   대형 뮤지컬 1건(486백만)이 나머지 16건(0.9~66백만)을 다 눌러 8건이 2px 막대가 되던 형태 실측 → 적정선에서 축을 끊는다.
//   ⚠ 값은 손대지 않는다 — 접는 건 **그리는 자리(y)** 뿐이고 눈금·막대 라벨·툴팁은 전부 실값 그대로다.
//   판정 = **후보 순회**(260806 개정 · 구 「하위 80% 지점」 단일 후보는 폐기 — 아래 260806 절이 정본 기술).
//   ⚠ 「바로 아래 값의 2배」 규칙은 260804에 **절단점 선택자**로서 폐기됐다 — 평의회3 실측: 3위가 67.25→67.26으로 0.02 움직이면
//     전 막대가 반토막 나고, 대형 뮤지컬이 2편이면 규칙이 조용히 꺼져 원래 문제로 되돌아갔다(이 차트는 매일 갱신되므로
//     어제 화면과 비교되는 게 우선이다). ⚠ 단, 260806에 같은 「2배」가 **후보 거부권**(선택자 아님)으로 재도입됐다 —
//     선택은 순회가 하고 2배는 「끊을 빈 구간이 있나」만 판정한다. ⚠ 그렇다고 절벽이 사라진 건 아니다 —
//     평의회3 실측(실데이터 47공연 분포 407,200회 섭동) = **신규 절벽 클래스 존재**(최상단 +0.0083% 이동에 B ×5.0·
//     접힘 5→1 · 원인 = `pos[0]<B*2` 경계에서 채택 후보가 4계단 건너뜀). 다만 ⓐ 발생률 2.4%/90일 ⓑ 진동 없음(1회 계단)
