function _bizDrawSeason(divId,stO){
  var _bs=stO||_bizState;   // [260723c] divId·stO = 메인 인라인 2면 재사용(기본 = 모달 불변)
  var div=document.getElementById(divId||'biz-season-chart');if(!div||!window.Plotly)return;
  var all=_bizClean();
  var sel=_bs.types||{};var selTypes=Object.keys(sel).filter(function(t){return sel[t];});
  var rows=all.filter(function(r){return selTypes.length?selTypes.indexOf(r._type)>=0:true;});
  var sm={};rows.forEach(function(r){var k=r._year+'|'+r._name;if(!sm[k])sm[k]={occs:[],dates:{},genre:r._genre||'기타',year:r._year,name:r._name};sm[k].occs.push(r._occ);if(r._date)sm[k].dates[r._date.getFullYear()+'-'+r._date.getMonth()+'-'+r._date.getDate()]=1;});
  var order=['클래식','뮤지컬','대중','발레/연극','어린이·가족','기타'];
  var shows=Object.keys(sm).map(function(k){var s=sm[k];s.occ=s.occs.reduce(function(a,b){return a+b;},0)/s.occs.length;s.회차=s.occs.length;s.진행일=Object.keys(s.dates||{}).length||1;if(order.indexOf(s.genre)<0)s.genre='기타';return s;});
  var __rb=_bs.rounds||'전체';if(__rb!=='전체')shows=shows.filter(function(s){var c=s.회차;return __rb==='1회'?c<=1:(__rb==='2~4회'?(c>=2&&c<=4):c>=5);});
  var __db=_bs.rundays||'전체';if(__db!=='전체')shows=shows.filter(function(s){var d=s.진행일;return __db==='단일'?d<=1:(__db==='2~3일'?(d>=2&&d<=3):d>=4);});
  var yg={};shows.forEach(function(s){var k=s.genre+'|'+s.year;(yg[k]=yg[k]||[]).push(s.occ);});
  var byG={};Object.keys(yg).forEach(function(k){var p=k.split('|');var g=p[0],y=+p[1];var arr=yg[k];(byG[g]=byG[g]||[]).push({y:y,occ:arr.reduce(function(a,b){return a+b;},0)/arr.length,n:arr.length});});
  var genres=order.filter(function(g){return byG[g]&&byG[g].length;});
  if(!genres.length){div.innerHTML='<div style="color:#aaa;text-align:center;padding:24px;font-size:12px">시즌 데이터 없음</div>';return;}
  var cy=_bs.year;var traces=[];
  genres.forEach(function(g){var arr=byG[g].sort(function(a,b){return a.y-b.y;});var col=_BIZ_GENRE_COLORS[g]||'#9CA3AF';
    traces.push({type:'scatter',mode:'lines+markers',name:g,x:arr.map(function(p){return p.y;}),y:arr.map(function(p){return Math.round(p.occ*10)/10;}),line:{color:col,width:2},marker:{color:col,size:arr.map(function(p){return p.y===cy?12:6;}),line:{color:'#fff',width:1}},text:arr.map(function(p){return 'n'+p.n;}),hovertemplate:g+' %{x}년<br>%{y:.1f}% (%{text})<extra></extra>'});});
  var shapes=[{type:'line',x0:cy,x1:cy,yref:'paper',y0:0,y1:1,line:{color:'#ccc',dash:'dot',width:1}}];
  var layout={height:300,margin:{t:10,r:20,b:36,l:44},paper_bgcolor:'#fff',plot_bgcolor:'#fff',font:{family:'inherit',size:11,color:_yrCss('--ink-2')},xaxis:{title:'연도',dtick:1,gridcolor:_yrCss('--line'),zeroline:false},yaxis:{title:'평균 점유율 %',range:[0,105],ticksuffix:'%',gridcolor:_yrCss('--line'),zeroline:false},showlegend:true,legend:{orientation:'h',y:-0.18,x:0.5,xanchor:'center',font:{size:10}},shapes:shapes};
  Plotly.react(div,traces,layout,{responsive:true,displayModeBar:false});
}

