    body.innerHTML='<div style="text-align:center;padding:60px;color:#888;font-size:14px">📭 '+escapeHtml(note)+'<div style="font-size:12px;color:#bbb;margin-top:8px">dash에서 동기화되면 자동 표시됩니다</div></div>';
    return;
  }
  const years=Array.from(new Set(all.map(function(r){return r._year;}))).sort(function(a,b){return b-a;});
  if(_bizState.year===null||years.indexOf(_bizState.year)<0){
    const defY=(new Date()).getFullYear()-1;
    _bizState.year=years.indexOf(defY)>=0?defY:years[0];
  }
  const yearAll=all.filter(function(r){return r._year===_bizState.year;});
  const types=Array.from(new Set(yearAll.map(function(r){return r._type;}).filter(Boolean)));
  types.sort(function(a,b){return _BIZ_TYPE_ORDER.indexOf(a)-_BIZ_TYPE_ORDER.indexOf(b);});
  let anyChecked=false;
  types.forEach(function(t){if(_bizState.types[t]===undefined)_bizState.types[t]=(t==='기획');if(_bizState.types[t])anyChecked=true;});
  if(!anyChecked&&types.length)_bizState.types[types[0]]=true;
  const selTypes=types.filter(function(t){return _bizState.types[t];});
