  years.forEach(function(y){h+='<option value="'+y+'"'+(y===_bizState.year?' selected':'')+'>'+y+'년</option>';});
  h+='</select><div style="display:flex;gap:8px;flex-wrap:wrap">';
  types.forEach(function(t){const on=!!_bizState.types[t];const only=selTypes.length===1&&on;
    h+='<label class="fbar-chip'+(on?' on':'')+(only?' lock':'')+'"><input type="checkbox" '+(on?'checked':'')+(only?' disabled':'')+' onchange="_bizToggleType(\''+_anaEsc(t)+'\')">'+escapeHtml(t)+'</label>';   // [260723 평의회4] 이스케이프 경화 = _anaEsc(신규 인라인 칩과 동시 — 쌍둥이)
  });
  h+='</div></div>';
  if(!list.length){h+='<div style="text-align:center;padding:40px;color:#888">해당 연도/분류 데이터가 없습니다</div>';body.innerHTML=h;return;}
  h+='<div id="biz-chart" style="height:430px;margin-bottom:14px"></div>';
  h+='<div style="font-size:13px;font-weight:700;color:var(--ink);margin:6px 0 4px">장르 벤치마크 <span style="font-weight:400;color:#999;font-size:11px">— ◆장르 평균 · ⭐'+_bizState.year+'년 공연 · 점=전체 기간 (선택 분류 기준)</span></div><div style="display:flex;gap:16px;flex-wrap:wrap;align-items:center;margin:2px 0 10px">'+_chipRow('회차',['전체','1회','2~4회','5회+'],_bizState.rounds,'_bizSetRounds')+_chipRow('진행일',['전체','단일','2~3일','4일+'],_bizState.rundays,'_bizSetRunDays')+'</div><div id="biz-genre-chart" style="height:300px;margin-bottom:18px"></div>';
  h+='<div style="font-size:13px;font-weight:700;color:var(--ink);margin:6px 0 4px">시즌(연도)별 장르 점유율 추세 <span style="font-weight:400;color:#999;font-size:11px">— 장르별 연평균 점유율(기획·발권유료÷기준석) · 큰점='+_bizState.year+'년 · 위 분류/필터 반영</span></div><div id="biz-season-chart" style="height:300px;margin-bottom:18px"></div>';
  const total=list.length,avgAll=list.reduce(function(a,g){return a+g.avg;},0)/list.length,maxAll=Math.max.apply(null,list.map(function(g){return g.avg;}));
