  body.innerHTML=h;
  _bizEnsurePlotly(function(){ _bizDrawChart(list, selTypes.length>1); _bizDrawGenreBench(); _bizDrawSeason(); _accordionize('biz-body'); _rvSweep(body); });   // [260810-2] 리빌 = 아코디언 래핑 **뒤**(직계 자식이 확정된 다음 · 판매 보드 _salesSectionPop 순서와 동일)
}
// ============================================================
// 연간 실적 (사업 현황) — 예울마루(망마·장도) 2012~2025 확정 + 2026 상반기 잠정 연간 실적 표를 '그대로' 살린 보드.
//   [260805-38 → 260807 개정] 부제의 `(발권유료)` 딱지는 **폐지**했다 — 2026 공연이 이제 `운영_공연대장`의
//   **발권유료 + 발권초대**(= 무료 포함)라 다른 해와 **같은 자**다. 구판은 회차 원장의 발권유료만 써서
//   2026이 실제보다 작게 보였다(실측 9,568 → 23,601 · 2.5배). 근거 = 공연대장의 유료+초대가 _YR 관람인원과
//   과거 연도에서 정확히 일치한다(전체 9/15년 · 기획·대관만 10/15년 · 2025 Δ8 · 2012~2022는 대장의 월별 집계 셀
//   `관람객`이 _YR과 전건 일치 = 취합본의 원천이 이 대장이었다). 갱신 = `node tools/build_annual_yr.mjs --sync-partial --from-live`.
//   ⚠ 남은 잠정 사유는 「상반기까지」 하나뿐 — 전시는 여전히 전시DB 기준(2025 26,785 vs 20,217 차이는 그대로다).
//   실측표 = docs/reports/260805-38_연간실적_정제도_실측.html · 260807 = docs/reports/260807_연간실적_2026기준_전후.html
//   진입 = nav 「대시보드 ▸ 연간 실적」(260731 재편 — 구 '사업 현황' 대메뉴 id=bizstatus 폐지) · 모바일 더보기 시트. 데이터 = 아래 _YR 상수(엑셀 원본 무손실).
//   골격 = openBusinessBoard/_bizRender 100% 계승(모달·.fbar-chip·Plotly·KPI 카드·표) · 색은 팔레트 토큰만
//   (Plotly는 CSS var()를 못 읽어 getComputedStyle로 런타임 해석 → 소스 raw hex 0, 게이트 총량 동결 유지).
//   필터 = 연도별(select) + 공연/전시/교육 별(칩) · 애니메이션 = KPI 카운트업·막대 성장·표 페이드업.
// ============================================================
// [260813] 연간 실적 상수(_YR) = **`data/annual_yr.js`로 이관**(기계산출물 · `tools/build_annual_yr.mjs`가 읽고 쓴다).
//   여기 다시 적지 마라 — 두 벌이 되는 순간 갈린다. 값을 바꾸려면 그 빌더를 돌려라.

var _yrState={cats:{'공연':true,'전시':true,'교육':true},metric:'인원',year:'all',esc:null,opened:false};
var _YR_METRICS=[{k:'인원',l:'관람·수강'},{k:'횟수',l:'횟수·건수'},{k:'일수',l:'일수'},{k:'나눔',l:'문화나눔'}];
var _YR_CATLIST=['공연','전시','교육'];
// [260813 운영자 「관람 수강 추이 차트의 **모양만** 따라하라는 것이지 그대로 가져오라는 게 아니라 거기에 매출을 채우라는 거임.
//   안채워지는 부분은 0으로 하면 되는거고」]
//   → 새 차트를 만들지 않는다. 정본 `_yrDrawChart`가 `st.metric`으로 지표를 고르므로, **매출 지표 한 줄을 얹는다**.
//     그리기 코드·색·라벨·콜아웃 규약은 한 글자도 안 바뀐다 = 모양이 같을 수밖에 없다.
//   ⚠ `_YR` 파일(기계산출물)에는 안 적는다 — 사업비 씨앗에서 **그릴 때마다 센다**(파생값 미저장 계약과 같은 축).
//   ⚠ `_YR.years`에 맞춰 자리를 채우고, 사업비 자료가 없는 해는 **0**(운영자 지시).

_bizOvYrRevRows:
function _bizOvYrRevRows(){
  try{
    if(typeof _YR==='undefined'||!_YR.cats||typeof BIZ_FIN==='undefined')return false;
    _YR_CATLIST.forEach(function(cat){
      var c=_YR.cats[cat]; if(!c||!c.rows)return;
      var v=_YR.years.map(function(y){
        var rs=(BIZ_FIN.years&&BIZ_FIN.years[y]&&BIZ_FIN.years[y].rows)||[];
        var t=0; rs.forEach(function(r){ if(r.cat===cat)t+=Number(r.rev)||0; });
        return t;   // 자료 없는 해 = 0
      });
      var hit=null; c.rows.forEach(function(r){ if(r.key==='매출')hit=r; });
      if(hit)hit.v=v; else c.rows.push({key:'매출',v:v});
    });
    return true;
  }catch(_e){ console.warn('[bizov 매출 지표]',_e); return false; }
}
var _BIZOV_ST={cats:{'공연':true,'전시':true,'교육':true},metric:'매출',year:'all'};   // 사업 개요 차트 전용 고정 상태(판매 현황 `_YRM_ST` 무오염)
